+
+impl<'b, 'a> Peeled<'b, 'a> {
+    /// Whether the call has the type `expr` is declared with, so that its declaration (`resolver::callee`) describes
+    /// the call.
+    pub(super) fn keeps_identity(&self) -> bool {
+        matches!(self.identity, Identity::Kept)
+    }
