+            TSType::TSTypeReference(_) => true,
+            TSType::TSParenthesizedType(inner) => named(&inner.type_annotation),
+            TSType::TSUnionType(union) => {
+                union.types.iter().any(|member| matches!(member, TSType::TSTypeReference(_)))
