1	//! Every component detection form, crossed with every wrapper TypeScript can put around the expression it reads,
2	//! extracts the same component as the unwrapped form while the wrapper keeps the callee's type, and what the replacing
3	//! assertion says when it does not (`Expect`). OXC 0.159 stopped flattening `(f<T>)(x)` and `extends (B<T>)` into the
4	//! enclosing call or heritage clause, which is how a wrapper first broke detection.
5	
6	use super::*;
7	
8	const HEADER: &str = "import React, { forwardRef, memo, Component, PureComponent } from 'react';\n\
9	                      interface Props { label?: string }\n";
10	
11	/// A wrapper around a callee or `extends` target `base` and its type arguments `args`, as written in source.
12	#[derive(Clone, Copy, Debug)]
13	enum Callee {
14	    Plain,
15	    Parenthesized,
16	    /// `(f<T>)`: the instantiation OXC 0.159 keeps as a node of its own.
17	    InstantiationInParens,
18	    InstantiationInDoubleParens,
19	    As,
20	    Satisfies,
21	    NonNull,
22	    InstantiationNonNull,
23	    /// `(<typeof f>f)<T>`: only valid where JSX is not.
24	    TypeAssertion,
25	    /// `(f<T> satisfies G)`: `satisfies` keeps the type of what it checks, so the type arguments still name the props.
26	    InstantiationSatisfies,
27	    /// `(React).forwardRef`: the namespace a member is read from is wrapped, not the callee. A bare name has none.
28	    ObjectParenthesized,
29	    ObjectAs,
30	    ObjectNonNull,
31	    /// `(f as any)`: `any` says nothing about the callee, so its name still does.
32	    AsAny,
33	    /// `(f as (...args: any[]) => object)`: the assertion states a result that is no component.
34	    AsObjectResult,
35	    /// `(f as unknown as (...args: any[]) => object)`: the same through `unknown`.
36	    AsUnknownAsObjectResult,
37	    /// `(f as (...args: any[]) => React.FC<…>)`: a named result the extractor does not resolve.
38	    AsOtherComponentResult,
39	    /// `(React as object).forwardRef`: the namespace is asserted to a type with no such member.
40	    ObjectAsObject,
41	    /// `(<(...args: any[]) => object>f)`: the `<T>x` spelling of `AsObjectResult`, only valid where JSX is not.
42	    TypeAssertionObjectResult,
43	}
44	
45	/// What a row extracts, against the unwrapped form.
46	#[derive(Debug, PartialEq)]
47	enum Expect {
48	    /// The assertion keeps the callee's type (none, `typeof` itself, `any`): the unwrapped form's component.
49	    Same,
50	    /// The assertion replaces the callee's type with a named result that is not resolved: the name still says what the
51	    /// call is, but the callee's own declaration no longer describes it, so the mapping has no wrapper callee.
52	    SameWithoutCallee,
53	    /// The assertion states a result that is no named type: nothing is read through the callee's name.
54	    Declined,
55	}
56	
57	impl Callee {
58	    const ALL: [Self; 19] = [
59	        Self::Plain,
60	        Self::Parenthesized,
61	        Self::InstantiationInParens,
62	        Self::InstantiationInDoubleParens,
63	        Self::As,
64	        Self::Satisfies,
65	        Self::NonNull,
66	        Self::InstantiationNonNull,
67	        Self::TypeAssertion,
68	        Self::InstantiationSatisfies,
69	        Self::ObjectParenthesized,
70	        Self::ObjectAs,
71	        Self::ObjectNonNull,
72	        Self::AsAny,
73	        Self::AsObjectResult,
74	        Self::AsUnknownAsObjectResult,
75	        Self::AsOtherComponentResult,
76	        Self::ObjectAsObject,
77	        Self::TypeAssertionObjectResult,
78	    ];
79	
80	    fn expect(self) -> Expect {
81	        match self {
82	            Self::Plain
83	            | Self::Parenthesized
84	            | Self::InstantiationInParens
85	            | Self::InstantiationInDoubleParens
86	            | Self::As
87	            | Self::Satisfies
88	            | Self::NonNull
89	            | Self::InstantiationNonNull
90	            | Self::TypeAssertion
91	            | Self::InstantiationSatisfies
92	            | Self::ObjectParenthesized
93	            | Self::ObjectAs
94	            | Self::ObjectNonNull
95	            | Self::AsAny => Expect::Same,
96	            Self::AsOtherComponentResult => Expect::SameWithoutCallee,
97	            Self::AsObjectResult
98	            | Self::AsUnknownAsObjectResult
99	            | Self::ObjectAsObject
100	            | Self::TypeAssertionObjectResult => Expect::Declined,
101	        }
102	    }
103	
104	    fn wrap(self, base: &str, args: &str) -> String {
105	        let (object, member) = base.split_once('.').map_or((None, base), |(object, member)| (Some(object), member));
106	        match self {
107	            Self::Plain => format!("{base}{args}"),
108	            Self::Parenthesized => format!("({base}){args}"),
109	            Self::InstantiationInParens => format!("({base}{args})"),
110	            Self::InstantiationInDoubleParens => format!("(({base}{args}))"),
111	            Self::As => format!("({base} as typeof {base}){args}"),
112	            Self::Satisfies => format!("({base} satisfies typeof {base}){args}"),
113	            Self::NonNull => format!("{base}!{args}"),
114	            Self::InstantiationNonNull => format!("({base}{args})!"),
115	            Self::TypeAssertion => format!("(<typeof {base}>{base}){args}"),
116	            Self::InstantiationSatisfies => format!("({base}{args} satisfies typeof {base})"),
117	            Self::ObjectParenthesized => {
118	                object.map_or_else(|| format!("{base}{args}"), |o| format!("({o}).{member}{args}"))
119	            }
120	            Self::ObjectAs => {
121	                object.map_or_else(|| format!("{base}{args}"), |o| format!("({o} as any).{member}{args}"))
122	            }
123	            Self::ObjectNonNull => object.map_or_else(|| format!("{base}{args}"), |o| format!("{o}!.{member}{args}")),
124	            Self::AsAny => format!("({base} as any){args}"),
125	            Self::AsObjectResult => format!("({base} as (...args: any[]) => object){args}"),
126	            Self::AsUnknownAsObjectResult => format!("({base} as unknown as (...args: any[]) => object){args}"),
127	            Self::AsOtherComponentResult => {
128	                format!("({base} as (...args: any[]) => React.FC<{{ other?: number }}>){args}")
129	            }
130	            Self::ObjectAsObject => {
131	                object.map_or_else(|| format!("{base}{args}"), |o| format!("({o} as object).{member}{args}"))
132	            }
133	            Self::TypeAssertionObjectResult => format!("(<(...args: any[]) => object>{base}){args}"),
134	        }
135	    }
136	}
137	
138	/// A wrapper around a whole initializer or default-exported expression.
139	#[derive(Clone, Copy, Debug)]
140	enum Value {
141	    Plain,
142	    Parenthesized,
143	    As,
144	    Satisfies,
145	    NonNull,
146	    TypeAssertion,
147	}
