332	/// What a component's extraction is, without where it sits in the file: the wrappers move its span.
333	fn extracted(path: &Utf8Path, source: &str) -> (Vec<serde_json::Value>, Vec<String>) {
334	    let data = parse_file(path, &format!("{HEADER}{source}"));
335	    let parse_errors: Vec<String> = data
336	        .diagnostics
337	        .iter()
338	        .filter(|diagnostic| diagnostic.code == DiagnosticCode::ParseError)
339	        .map(|diagnostic| diagnostic.message.clone())
340	        .collect();
341	    let mappings = data
342	        .component_mappings
343	        .iter()
344	        .map(|mapping| {
345	            let mut value = serde_json::to_value(mapping).unwrap();
346	            let object = value.as_object_mut().unwrap();
347	            object.remove("span_start");
348	            object.remove("span_end");
349	            value
350	        })
351	        .collect();
352	    (mappings, parse_errors)
353	}
