355	/// An assertion replaces the type of the instantiation beneath it, so its type arguments no longer name the props.
356	#[test]
357	fn type_arguments_beneath_an_assertion_do_not_name_the_props() {
358	    for callee in ["(forwardRef<HTMLButtonElement, Props> as any)", "(<any>forwardRef<HTMLButtonElement, Props>)"] {
359	        let source = format!("export const Button = {callee}(({{ label = 'x' }}, ref) => {RENDER});");
360	        let (mappings, errors) = extracted(Utf8Path::new("/fixtures/Button.ts"), &source);
361	        assert!(errors.is_empty(), "{errors:?}");
362	        assert_eq!(mappings, Vec::<serde_json::Value>::new(), "{source}");
363	    }
364	}
