367	/// through every wrapper of the callee, of its namespace and of the first argument.
368	#[test]
369	fn object_assign_attaches_its_inline_members_through_every_wrapper() {
370	    let sources = |assign: &str, first: &str| {
371	        format!(
372	            "{HEADER}interface ItemProps {{ size?: string }}\n\
373	             function Impl(props: Props) {{ return {RENDER}; }}\n\
374	             export const Root = {assign}({first}, {{ Item: (props: ItemProps) => {RENDER} }});"
375	        )
