377	    let path = Utf8Path::new("/fixtures/Root.tsx");
378	    let (expected, errors) = extracted(path, &sources("Object.assign", "Impl"));
379	    assert!(errors.is_empty(), "{errors:?}");
380	    let names = |mappings: &[serde_json::Value]| -> Vec<String> {
381	        let mut names: Vec<String> =
382	            mappings.iter().filter_map(|mapping| mapping["component_name"].as_str().map(str::to_owned)).collect();
383	        names.sort();
384	        names
385	    };
386	    assert_eq!(names(&expected), ["Item", "Root"], "{expected:#?}");
387	    let mut failures = Vec::new();
388	    for assign in [
389	        "(Object).assign",
390	        "(Object as typeof Object).assign",
391	        "Object!.assign",
392	        "(Object satisfies ObjectConstructor).assign",
393	    ] {
394	        for first in ["Impl", "(Impl)", "Impl as typeof Impl", "Impl!"] {
395	            let source = sources(assign, first);
396	            let (actual, errors) = extracted(path, &source);
397	            if !errors.is_empty() || actual != expected {
398	                failures.push(format!("{assign}({first}, …): {errors:?}\n{source}\nactual {:?}", names(&actual)));
399	            }
400	        }
401	    }
402	    assert!(failures.is_empty(), "{} forms differ from the plain one:\n{}", failures.len(), failures.join("\n\n"));
403	}
