405	#[test]
406	fn every_detection_form_extracts_the_same_component_through_every_wrapper() {
407	    let mut failures = Vec::new();
408	    for form in forms() {
409	        // A type assertion `<T>x` is JSX in a `.tsx` file; the `.ts` rows read it, and a `.ts` file importing React
410	        // is read for components.
411	        for extension in ["tsx", "ts"] {
412	            let path = Utf8PathBuf::from(format!("/fixtures/{}.{extension}", form.stem));
413	            let plain = (form.source)(Callee::Plain, Value::Plain);
414	            let (unwrapped, errors) = extracted(&path, &plain);
415	            assert!(errors.is_empty(), "{}: {errors:?}", form.name);
416	            let [mapping] = unwrapped.as_slice() else {
417	                panic!("{}: expected one component, got {unwrapped:#?}", form.name)
418	            };
419	            assert_eq!(mapping["component_name"], "Button", "{}", form.name);
420	            assert_eq!(mapping["props_type_name"], "Props", "{}", form.name);
421	            let rows = Callee::ALL
422	                .iter()
423	                .map(|&callee| (callee, Value::Plain))
424	                .chain(Value::ALL.iter().map(|&value| (Callee::Plain, value)));
425	            for (callee, value) in rows {
426	                let jsx_only = extension == "tsx";
427	                if jsx_only
428	                    && (matches!(callee, Callee::TypeAssertion | Callee::TypeAssertionObjectResult)
429	                        || matches!(value, Value::TypeAssertion))
430	                {
431	                    continue;
432	                }
433	                let source = (form.source)(callee, value);
434	                let (actual, errors) = extracted(&path, &source);
435	                // A form that reads no callee is written the same whatever the callee wrapper.
436	                let expect = if source == plain { Expect::Same } else { callee.expect() };
437	                let expected: Vec<serde_json::Value> = match expect {
438	                    Expect::Same => unwrapped.clone(),
439	                    Expect::SameWithoutCallee => unwrapped
440	                        .iter()
441	                        .map(|mapping| {
442	                            let mut mapping = mapping.clone();
443	                            mapping["wrapper_callee"] = serde_json::Value::Null;
444	                            mapping
445	                        })
446	                        .collect(),
447	                    Expect::Declined => Vec::new(),
448	                };
449	                if !errors.is_empty() {
450	                    failures.push(format!(
451	                        "{} [{callee:?}, {value:?}] .{extension}: parse errors {errors:?}\n{source}",
452	                        form.name
453	                    ));
454	                } else if actual != expected {
455	                    failures.push(format!(
456	                        "{} [{callee:?}, {value:?}] .{extension}, {expect:?}:\n{source}\nexpected {expected:#?}\nactual {actual:#?}",
457	                        form.name
458	                    ));
459	                }
460	            }
461	        }
462	    }
463	    assert!(failures.is_empty(), "{} rows differ from what they expect:\n\n{}", failures.len(), failures.join("\n\n"));
464	}
