466	/// `Object.assign` through an identity cast makes `Root` an alias of `Impl`, and the inline member scan reads the call
467	/// through the same predicate, so `Item` is found with it. A cast of `Object` to another type finds neither.
468	/// (`Impl` is not published under its own name while `Root` aliases it.)
469	#[test]
470	fn an_object_assign_through_an_identity_cast_attaches_its_inline_members() {
471	    let found = |object: &str| {
472	        let source = format!(
473	            "interface P {{ a: string }}\n\
474	             interface ItemProps {{ b: string }}\n\
475	             function Impl(props: P) {{ return <div />; }}\n\
476	             export const Root = {object}.assign(Impl, {{ Item: (props: ItemProps) => <div /> }});"
477	        );
478	        let data = parse_file(Utf8Path::new("/test/compound.tsx"), &source);
479	        let mut found: Vec<(String, String)> =
480	            data.component_mappings.iter().map(|m| (m.component_name.clone(), m.props_type_name.to_string())).collect();
481	        found.sort_unstable();
482	        found
483	    };
484	    let pair = |name: &str, props: &str| (name.to_owned(), props.to_owned());
485	    for object in ["Object", "(Object as typeof Object)", "(Object as any)", "(Object)!"] {
486	        assert_eq!(found(object), [pair("Item", "ItemProps"), pair("Root", "P")], "{object}");
487	    }
488	    // Not an alias, `Root` takes nothing and `Impl` stands as its own component.
489	    assert_eq!(found("(Object as object)"), [pair("Impl", "P")]);
490	}
