492	/// A PascalCase callee is rendering evidence only while its name describes the call: an assertion stating a result
493	/// that is no named type takes it away; a named or React result, `typeof` itself and `any` leave it.
494	#[test]
495	fn an_asserted_callee_renders_only_when_the_assertion_leaves_a_named_result() {
496	    let rows = [
497	        ("(Object as (value: object) => object)", false),
498	        ("(Object as unknown as (value: object) => string)", false),
499	        ("(Object as { (value: object): object })", false),
500	        ("(Object as (value: object) => React.ReactElement)", true),
501	        ("(Object as (value: object) => React.ReactElement | null)", true),
502	        ("(Object as F)", true),
503	        ("(Object as typeof Object)", true),
504	        ("(Object as any)", true),
505	        ("Object", true),
506	    ];
507	    for (callee, renders) in rows {
508	        let source = format!(
509	            "import React from 'react';\n\
510	             interface Props {{ a: string }}\n\
511	             export const Normalize = (props: Props) => {callee}(props);"
512	        );
513	        let data = parse_file(Utf8Path::new("/test/normalize.tsx"), &source);
514	        let names: Vec<&str> = data.component_mappings.iter().map(|m| m.component_name.as_str()).collect();
515	        let expected: &[&str] = if renders { &["Normalize"] } else { &[] };
